// Minimalna demonstracja modelu embedded - ten sam Apache Tomcat co
// w klasycznym WAR-owym wdrozeniu, tylko uruchomiony programowo z main().

Tomcat tomcat = new Tomcat();
tomcat.setBaseDir(Files.createTempDirectory("lesson02").toString());
tomcat.getConnector().setPort(0);

Context context = tomcat.addContext("", null);
Tomcat.addServlet(context, "infoServlet", new ContainerInfoServlet());
context.addServletMappingDecoded("/info", "infoServlet");

try {
    tomcat.start();
    int port = tomcat.getConnector().getLocalPort();
    // wyslij zadanie GET na http://localhost:<port>/info
} finally {
    tomcat.stop();
    tomcat.destroy();
}
